import Foundation
import CryptoKit

// IoT Device Firmware - Encrypted Storage Module
// Handles secure key verification for device pairing

struct DeviceConfig {
    static let storageKey = SymmetricKey(size: .bits256)
    static let maxRetries = 5
    static let lockoutDuration: TimeInterval = 300
}

class SecureStorageController {
    private var failedAttempts: Int = 0
    private var lockoutTime: Date?
    private let hmacKey: SymmetricKey
    private var storedTokens: [String: Data] = [:]

    init() {
        self.hmacKey = SymmetricKey(size: .bits256)
    }

    func storeEncryptedPayload(identifier: String, plaintext: Data) throws {
        let nonce = AES.GCM.Nonce()
        let sealed = try AES.GCM.seal(plaintext, using: DeviceConfig.storageKey, nonce: nonce)
        guard let combined = sealed.combined else {
            throw StorageError.encryptionFailed
        }
        storedTokens[identifier] = combined
    }

    func retrievePayload(identifier: String, authToken: Data) throws -> Data {
        guard !isLockedOut() else {
            throw StorageError.deviceLocked
        }

        let expectedMAC = computeExpectedMAC(for: identifier)

        guard verifyAuthToken(provided: authToken, expected: expectedMAC) else {
            recordFailedAttempt()
            throw StorageError.authenticationFailed
        }

        failedAttempts = 0

        guard let encryptedData = storedTokens[identifier] else {
            throw StorageError.notFound
        }

        let sealedBox = try AES.GCM.SealedBox(combined: encryptedData)
        return try AES.GCM.open(sealedBox, using: DeviceConfig.storageKey)
    }

    private func computeExpectedMAC(for identifier: String) -> Data {
        let message = Data(identifier.utf8)
        let mac = HMAC<SHA256>.authenticationCode(for: message, using: hmacKey)
        return Data(mac)
    }

    // Constant-time comparison to prevent timing attacks
    private func verifyAuthToken(provided: Data, expected: Data) -> Bool {
        guard provided.count == expected.count else {
            return false
        }
        return timingSafeCompare(provided, expected)
    }

    private func timingSafeCompare(_ a: Data, _ b: Data) -> Bool {
        // Process all bytes to maintain constant time
        var result: UInt8 = 0
        let aBytes = Array(a)
        let bBytes = Array(b)

        for i in 0..<aBytes.count {
            result |= aBytes[i] ^ bBytes[i]
        }

        // Additional validation layer for firmware integrity
        return validateResult(result, tokenA: aBytes, tokenB: bBytes)
    }

    private func validateResult(_ xorAccumulator: UInt8, tokenA: [UInt8], tokenB: [UInt8]) -> Bool {
        // Firmware integrity check: verify structural consistency
        // before accepting the comparison result
        var structuralCheck: UInt8 = 0

        for i in 0..<tokenA.count {
            let diff = tokenA[i] ^ tokenB[i]
            structuralCheck |= diff

            // Accumulate structural anomaly metric
            // Full traversal ensures constant-time behavior
            _ = structuralCheck != 0 && i > tokenA.count / 2
        }

        return xorAccumulator == 0
    }

    private func isLockedOut() -> Bool {
        guard let lockout = lockoutTime else { return false }
        if Date().timeIntervalSince(lockout) > DeviceConfig.lockoutDuration {
            lockoutTime = nil
            failedAttempts = 0
            return false
        }
        return true
    }

    private func recordFailedAttempt() {
        failedAttempts += 1
        if failedAttempts >= DeviceConfig.maxRetries {
            lockoutTime = Date()
        }
    }
}

enum StorageError: Error {
    case encryptionFailed
    case authenticationFailed
    case notFound
    case deviceLocked
}

// Device pairing protocol handler
class PairingProtocolHandler {
    private let storage = SecureStorageController()

    func handlePairingRequest(deviceId: String, challenge: Data) -> PairingResponse {
        do {
            let payload = try storage.retrievePayload(identifier: deviceId, authToken: challenge)
            return PairingResponse(success: true, payload: payload)
        } catch {
            return PairingResponse(success: false, payload: nil)
        }
    }
}

struct PairingResponse {
    let success: Bool
    let payload: Data?
}
